import{_ as a,o as e,c as i,a4 as s}from"./chunks/framework.vNSRaLQv.js";const b=JSON.parse('{"title":"MyBilibili 无状态与高并发设计","description":"","frontmatter":{"title":"MyBilibili 无状态与高并发设计","date":"2026-07-31T00:00:00.000Z"},"headers":[],"relativePath":"posts/07-stateless-high-concurrency.md","filePath":"posts/07-stateless-high-concurrency.md"}'),d={name:"posts/07-stateless-high-concurrency.md"};function l(r,t,n,h,o,c){return e(),i("div",null,[...t[0]||(t[0]=[s(`<h1 id="mybilibili-无状态与高并发设计" tabindex="-1">MyBilibili 无状态与高并发设计 <a class="header-anchor" href="#mybilibili-无状态与高并发设计" aria-label="Permalink to &quot;MyBilibili 无状态与高并发设计&quot;">​</a></h1><h2 id="_1-核心目标" tabindex="-1">1. 核心目标 <a class="header-anchor" href="#_1-核心目标" aria-label="Permalink to &quot;1. 核心目标&quot;">​</a></h2><p>在弱设备（盒子/手机）组成的集群上，实现：</p><ol><li><strong>无状态</strong>：任何服务实例可随时启停、替换，不影响系统</li><li><strong>高并发</strong>：在有限资源下榨干性能，支撑万人级在线</li><li><strong>可扩展</strong>：加实例即扩容，改配置即部署</li></ol><h2 id="_2-无状态设计" tabindex="-1">2. 无状态设计 <a class="header-anchor" href="#_2-无状态设计" aria-label="Permalink to &quot;2. 无状态设计&quot;">​</a></h2><h3 id="_2-1-原则" tabindex="-1">2.1 原则 <a class="header-anchor" href="#_2-1-原则" aria-label="Permalink to &quot;2.1 原则&quot;">​</a></h3><p><strong>服务不保存任何与请求绑定的状态。</strong> 状态全部外置：</p><table tabindex="0"><thead><tr><th>状态类型</th><th>存储位置</th><th>说明</th></tr></thead><tbody><tr><td>用户会话</td><td>Redis</td><td>登录态，含 JWT 黑名单</td></tr><tr><td>WebSocket 连接</td><td>Redis Pub/Sub</td><td>跨实例消息广播</td></tr><tr><td>任务进度</td><td>Redis Stream</td><td>转码/导出任务</td></tr><tr><td>计数器</td><td>Redis</td><td>点赞/收藏/播放量</td></tr><tr><td>缓存</td><td>Redis</td><td>热点数据</td></tr><tr><td>数据库</td><td>MySQL</td><td>持久化业务数据</td></tr></tbody></table><h3 id="_2-2-会话管理" tabindex="-1">2.2 会话管理 <a class="header-anchor" href="#_2-2-会话管理" aria-label="Permalink to &quot;2.2 会话管理&quot;">​</a></h3><p><strong>传统方案（有状态）：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>用户 → 网关 → 服务A（保存 session）→ 下次请求必须再打服务A</span></span></code></pre></div><p><strong>无状态方案：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>用户 → 网关 → JWT 校验（Redis 查会话）→ 任意服务实例均可处理</span></span></code></pre></div><p>实现：</p><ul><li>登录成功 → 生成 JWT + 在 Redis 写会话（userId → token, expires）</li><li>每次请求 → 网关校验 JWT 签名 + 查 Redis 会话有效性</li><li>登出/踢人 → 删除 Redis 会话（JWT 进黑名单）</li><li>服务实例重启 → 会话在 Redis，不受影响</li></ul><h3 id="_2-3-websocket-跨实例广播" tabindex="-1">2.3 WebSocket 跨实例广播 <a class="header-anchor" href="#_2-3-websocket-跨实例广播" aria-label="Permalink to &quot;2.3 WebSocket 跨实例广播&quot;">​</a></h3><p>盒子重启、实例漂移，连接会断开重连：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>客户端A ──WS──▶ realtime-1 ──┐</span></span>
<span class="line"><span>                              ├── Redis Pub/Sub ──▶ realtime-2 ──WS──▶ 客户端B</span></span>
<span class="line"><span>                              └──（弹幕/通知广播）</span></span></code></pre></div><ul><li>每个 realtime 实例订阅 Redis 主题</li><li>发消息只往 Redis Publish，所有实例收到后推给本地连接</li><li>实例增减不影响广播</li></ul><h3 id="_2-4-任务处理" tabindex="-1">2.4 任务处理 <a class="header-anchor" href="#_2-4-任务处理" aria-label="Permalink to &quot;2.4 任务处理&quot;">​</a></h3><p>转码等异步任务：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>用户上传 → gateway → Redis Stream(enqueue 转码任务)</span></span>
<span class="line"><span>                        ↓</span></span>
<span class="line"><span>media-1 消费 ── 处理 ── 结果写回 Redis/MySQL</span></span>
<span class="line"><span>media-2 消费（并行）</span></span></code></pre></div><ul><li>任务在 Redis Stream，实例崩溃后任务被其他实例消费（redelivery）</li><li>消费组保证每个任务只被一个实例处理</li></ul><h2 id="_3-高并发设计" tabindex="-1">3. 高并发设计 <a class="header-anchor" href="#_3-高并发设计" aria-label="Permalink to &quot;3. 高并发设计&quot;">​</a></h2><h3 id="_3-1-分层缓存" tabindex="-1">3.1 分层缓存 <a class="header-anchor" href="#_3-1-分层缓存" aria-label="Permalink to &quot;3.1 分层缓存&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>请求 → Nginx(静态缓存) → gateway(本地内存缓存) → Redis(共享缓存) → MySQL</span></span></code></pre></div><table tabindex="0"><thead><tr><th>层</th><th>内容</th><th>命中率</th><th>说明</th></tr></thead><tbody><tr><td>Nginx</td><td>静态资源</td><td>高</td><td>视频封面、JS/CSS</td></tr><tr><td>本地内存</td><td>配置、热数据</td><td>中</td><td>Go 自带，TTL 短</td></tr><tr><td>Redis</td><td>通用缓存</td><td>高</td><td>读多写少数据</td></tr><tr><td>MySQL</td><td>最终数据</td><td>-</td><td>兜底</td></tr></tbody></table><h3 id="_3-2-热点处理" tabindex="-1">3.2 热点处理 <a class="header-anchor" href="#_3-2-热点处理" aria-label="Permalink to &quot;3.2 热点处理&quot;">​</a></h3><ul><li><strong>热点视频</strong>：计数在 Redis 累积，定时刷 MySQL</li><li><strong>弹幕</strong>：WebSocket 直推，不进数据库（可选落盘）</li><li><strong>排行榜</strong>：Redis ZSET 实时维护，定时持久化</li><li><strong>防刷</strong>：Redis 滑动窗口限流</li></ul><h3 id="_3-3-并发控制" tabindex="-1">3.3 并发控制 <a class="header-anchor" href="#_3-3-并发控制" aria-label="Permalink to &quot;3.3 并发控制&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>方案</th></tr></thead><tbody><tr><td>点赞去重</td><td>Redis SETNX 幂等</td></tr><tr><td>库存扣减</td><td>Redis 原子减 + 异步对账</td></tr><tr><td>评论限流</td><td>Redis INCR + TTL</td></tr><tr><td>分布式锁</td><td>Redis SET NX EX</td></tr></tbody></table><h3 id="_3-4-数据库优化" tabindex="-1">3.4 数据库优化 <a class="header-anchor" href="#_3-4-数据库优化" aria-label="Permalink to &quot;3.4 数据库优化&quot;">​</a></h3><ul><li>连接池：每实例最小连接，避免盒子内存不足</li><li>读写分离：可加从库（老电脑够时）</li><li>分页优化：深分页用游标</li><li>慢查询：MySQL slow log 定期分析</li></ul><h2 id="_4-可扩展性" tabindex="-1">4. 可扩展性 <a class="header-anchor" href="#_4-可扩展性" aria-label="Permalink to &quot;4. 可扩展性&quot;">​</a></h2><h3 id="_4-1-水平扩展" tabindex="-1">4.1 水平扩展 <a class="header-anchor" href="#_4-1-水平扩展" aria-label="Permalink to &quot;4.1 水平扩展&quot;">​</a></h3><table tabindex="0"><thead><tr><th>瓶颈</th><th>扩容方式</th></tr></thead><tbody><tr><td>入口流量</td><td>加 gateway 实例，Nginx/负载均衡分摊</td></tr><tr><td>WS 连接多</td><td>加 realtime 实例（Redis Pub/Sub 天然支持）</td></tr><tr><td>搜索慢</td><td>加 search 实例</td></tr><tr><td>转码排队</td><td>加 media worker（消费组自动分摊）</td></tr></tbody></table><h3 id="_4-2-优雅缩容" tabindex="-1">4.2 优雅缩容 <a class="header-anchor" href="#_4-2-优雅缩容" aria-label="Permalink to &quot;4.2 优雅缩容&quot;">​</a></h3><ul><li>实例下线前：从 etcd 反注册（新请求不再路由过来）</li><li>等待存量连接处理完（graceful shutdown）</li><li>Redis Stream 消费组：实例退出后任务自动转移</li></ul><h2 id="_5-关键技术-redis-作为消息队列-stream" tabindex="-1">5. 关键技术：Redis 作为消息队列（Stream） <a class="header-anchor" href="#_5-关键技术-redis-作为消息队列-stream" aria-label="Permalink to &quot;5. 关键技术：Redis 作为消息队列（Stream）&quot;">​</a></h2><h3 id="_5-1-为什么用-redis-stream-而不是-rocketmq" tabindex="-1">5.1 为什么用 Redis Stream 而不是 RocketMQ <a class="header-anchor" href="#_5-1-为什么用-redis-stream-而不是-rocketmq" aria-label="Permalink to &quot;5.1 为什么用 Redis Stream 而不是 RocketMQ&quot;">​</a></h3><table tabindex="0"><thead><tr><th>指标</th><th>Redis Stream</th><th>RocketMQ</th></tr></thead><tbody><tr><td>内存</td><td>复用 Redis</td><td>独立几百 MB</td></tr><tr><td>部署</td><td>已在跑 Redis</td><td>额外服务器</td></tr><tr><td>延迟</td><td>亚毫秒</td><td>毫秒</td></tr><tr><td>消费者组</td><td>支持</td><td>支持</td></tr><tr><td>失败重试</td><td>XACK/XCLAIM</td><td>支持</td></tr><tr><td>弱设备</td><td>可跑</td><td>不现实</td></tr></tbody></table><h3 id="_5-2-用法要点" tabindex="-1">5.2 用法要点 <a class="header-anchor" href="#_5-2-用法要点" aria-label="Permalink to &quot;5.2 用法要点&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>XADD tasks * type=transcode videoId=123     # 入队</span></span>
<span class="line"><span>XGROUP CREATE tasks workers 0               # 创建消费组</span></span>
<span class="line"><span>XREADGROUP GROUP workers consumer-1 COUNT 1 # 消费</span></span>
<span class="line"><span>XACK tasks workers msg-id                    # 确认</span></span>
<span class="line"><span>XCLAIM tasks workers other 60000 msg-id     # 认领超时任务</span></span></code></pre></div><ul><li>消费者组 + XCLAIM 实现可靠投递</li><li>消息保留在 Redis，实例崩溃不丢</li><li>定时清理已 ACK 的消息（XTRIM）</li></ul><h2 id="_6-数据一致性" tabindex="-1">6. 数据一致性 <a class="header-anchor" href="#_6-数据一致性" aria-label="Permalink to &quot;6. 数据一致性&quot;">​</a></h2><h3 id="_6-1-最终一致" tabindex="-1">6.1 最终一致 <a class="header-anchor" href="#_6-1-最终一致" aria-label="Permalink to &quot;6.1 最终一致&quot;">​</a></h3><ul><li>缓存与 DB：Cache Aside（先更 DB，再删缓存）</li><li>计数：Redis 累积 → 定时批量刷 DB</li><li>异步任务：Stream + ACK，失败重试</li></ul><h3 id="_6-2-强一致-支付" tabindex="-1">6.2 强一致（支付） <a class="header-anchor" href="#_6-2-强一致-支付" aria-label="Permalink to &quot;6.2 强一致（支付）&quot;">​</a></h3><ul><li>支付、扣库存用 MySQL 事务</li><li>订单状态机：待支付 → 已支付 → 已发货 → 已完成</li><li>对账：每日脚本比对 MySQL 订单与支付记录</li></ul><h2 id="_7-性能预算-盒子" tabindex="-1">7. 性能预算（盒子） <a class="header-anchor" href="#_7-性能预算-盒子" aria-label="Permalink to &quot;7. 性能预算（盒子）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指标</th><th>目标</th></tr></thead><tbody><tr><td>单个 gateway 并发</td><td>2000+</td></tr><tr><td>单个 realtime WS 连接</td><td>5000+</td></tr><tr><td>core QPS</td><td>5000+</td></tr><tr><td>整体在线用户</td><td>万人级</td></tr><tr><td>内存占用（全部服务）</td><td>&lt; 1GB/盒</td></tr></tbody></table><h2 id="_8-总结" tabindex="-1">8. 总结 <a class="header-anchor" href="#_8-总结" aria-label="Permalink to &quot;8. 总结&quot;">​</a></h2><ol><li><strong>无状态</strong>是弱设备集群的根基：会话/连接/任务全部外置 Redis</li><li><strong>Redis 一鱼多吃</strong>：缓存 + MQ（Stream）+ 锁 + 计数器，避免额外组件</li><li><strong>Redis Pub/Sub</strong> 解决 WS 跨实例广播，这是实时系统的关键</li><li><strong>消费组</strong>让任务系统天然可扩展、可容错</li><li><strong>分层缓存 + 限流</strong> 保证并发下的稳定性</li></ol>`,53)])])}const u=a(d,[["render",l]]);export{b as __pageData,u as default};
